#!/usr/bin/env python3
"""Record the exact pilot inputs and reject admitted pilot theorems.

Generated modules can contain unused declarations with sorry; this checks each
exported pilot theorem's transitive axiom list, not just build success. Native
evaluation axioms are also rejected. Opaque
Goose type axioms are reported, not silently treated as proved definitions.
"""
import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

here = Path(__file__).resolve().parent
repo = here.parent.parent
log = Path(sys.argv[1]).read_text()
proofs = sorted((here / "ProofCheck").glob("*.lean"))
expected = {name for proof in proofs for name in re.findall(r"^theorem (\w+)", proof.read_text(), re.M)}
found = {}
for name, body in re.findall(r"'Perennial\.github_com\.NethermindEth\.juno\.core\.(\w+)' depends on axioms: \[(.*?)\]", log, re.S):
    found[name] = [x.strip() for x in body.split(",") if x.strip()]
if set(found) != expected:
    sys.exit(f"missing/unexpected axiom reports: {set(found) ^ expected}")
if any("sorryAx" in ax for xs in found.values() for ax in xs):
    sys.exit("a pilot theorem depends on sorryAx")
if any("._native." in ax or ax in {"Lean.ofReduceBool", "Lean.trustCompiler"}
       for xs in found.values() for ax in xs):
    sys.exit("a pilot theorem depends on a native evaluation axiom")
if any(re.search(r"^\s*(axiom|opaque)\b|\b(sorry|admit)\b", proof.read_text(), re.M) for proof in proofs):
    sys.exit("a handwritten proof contains an opaque declaration or admission")
rev = subprocess.check_output(["git", "-C", str(here / ".tools/perennial"), "rev-parse", "HEAD"], text=True).strip()
if rev != (here / "perennial.rev").read_text().strip():
    sys.exit("Perennial differs from perennial.rev")
dirty = subprocess.check_output(["git", "-C", str(here / ".tools/perennial"), "status", "--porcelain", "--untracked-files=no"], text=True)
if dirty:
    sys.exit("the pinned Perennial checkout has tracked modifications")
inputs = [repo / "go.mod", repo / "go.sum", *proofs, here / "ProofCheck.lean", here / "lean-toolchain", here / "lake-manifest.json", here / "lakefile.toml", here / "check.sh", here / "bootstrap.sh", here / "audit.py"]
for rel in ["core", "core/felt", "utils/cbor/cursor", "utils/cbor/fastcbor", "utils/cbor/cmd/cborgen"]:
    inputs += [p for p in (repo / rel).glob("*.go") if not p.name.endswith("_test.go")]
inputs += list((here / "config").rglob("*.toml"))
axiom_sets = []
theorem_sets = {}
for name, axioms in found.items():
    if axioms not in axiom_sets:
        axiom_sets.append(axioms)
    theorem_sets[name] = axiom_sets.index(axioms)
report = {
    "status": "pilot only; full decoder correctness and performance gates pending",
    "perennial": rev,
    "go": subprocess.check_output(["go", "version"], text=True).strip(),
    "theorem_axiom_set": theorem_sets,
    "axiom_sets": axiom_sets,
    "sorryAx_in_pilot": False,
    "native_evaluation_axioms_in_pilot": False,
    "caveat": "Package initialization and relevant global ownership are preconditions. Generated opaque type axioms remain. End-to-end populated Header proofs still cover only a single inline Number field, including cleanup after a subsequent truncation at byte 9. General head/unsigned/container success contracts, container count/depth failures, slow-head rejection classification, scalar type/tag and extended-head truncation failures, and null-field contracts are proved separately; their full Header composition, general EOF and remaining error propagation are pending. The typed felt reader is proved against the independent FeltValid success relation: null/undefined produce nil, short arrays zero-fill, and extended arrays retain four unsigned limbs while consuming arbitrarily nested extras satisfying SkipValid. This covers independently chosen head/limb widths and arbitrary limb values, dispatch, pointer conversion, fresh owned allocation for arrays, exact suffix and cursor advancement without signed wraparound. Depth rejection covers all supported array heads. Atomic Skip success, simple/string/tag rejection and EOF are proved through the public wrapper, including exact consumption on success and cursor rollback with retained diagnostic offset on error. General recursive Skip success is proved for the independent SkipValid relation, including arrays/maps/accepted tags, chained-tag depth and both wide-felt shortcuts; all child hypotheses are discharged by well-founded induction on encoded length. This is not yet a converse or complete rejection theorem. Recursive Skip rejection and complete felt rejection/converse remain pending; subsequent head-error milestones are described below. Definite payload extraction and oversized-length rollback are proved, including exact borrowed ranges and suffixes. BytesBorrowed composes both contracts; String and its typed field reader propagate truncation while preserving prior field state. General UTF8 validation is pending: a reversed operand tuple in the pinned generic slice-index rule blocks the actual word-helper proof; a separate repair proposal awaits approval, and its expected-failure reproducer is outside the audited target. General ASCII folding and both name-matching passes are proved: success identifies a folded-name match and failure excludes all names. Distinct folded names give a unique result; Header and GasPrice satisfy that property. New-field bit updates and duplicate rejection with owned diagnostic names are proved. Matching and duplicate marking preserve fractional metadata ownership. Integer-key classification and int64-range rejection, wrong-key type/tag diagnostics, and text-body truncation are proved through public Key and alternate field lookup, preserving exact success suffixes or original cursor/input on error. The full batched ASCII helper is proved equivalent to every byte being below 128 for arbitrary input lengths, preserving whole-input ownership. Public Key returns exact borrowed slices and suffixes for inline/one-byte ASCII keys. These compose through otherField, name matching and marking into an independent FieldReadOutcome covering unknown/new/duplicate fields, fractional metadata and owned duplicate diagnostics after key consumption. The three masked cached comparisons are proved equivalent to encoded-prefix equality for keys up to 24 bytes, and actual generated Header/GasPrice entries satisfy that representation. The production NextField cached-hit branch preserves fractional metadata and whole input while advancing the cursor and field state exactly. Its guard now checks remaining length before addition; arithmetic proofs and an explicit signed-limit counterexample cover the overflow distinction. Empty cache search and public NextField EOF are proved at arbitrary nonnegative offsets with no input loads. General short-buffer find is proved against an independent prefix-result contract, including sorted early exit, exhaustion, matching and all miss branches with fractional metadata/input ownership. Actual Header/GasPrice tables satisfy ordering, nonempty-encoding and prefix-separation checks; prefix separation gives a unique matching index. Short-buffer table hits compose through slow/public NextField with exact key/suffix and pair/search-index updates, new-field bits or owned duplicate errors at the consumed-key offset. Short-buffer misses compose through slow/public NextField and ASCII otherField with unknown/new/duplicate outcomes. Word-based find is proved for arbitrary input lengths with cached short-key tables, including first-byte prefiltering, actual word/mask loads, comparison, sorted early exit and exhaustion. The actual complete Header/GasPrice tables satisfy this representation; tables with encoded keys longer than 24 bytes still need the word-path tail comparison. Unified search composes through the slow reader into general table-hit/new/duplicate and ASCII-miss outcomes. Expected-key word mismatch is proved to preserve state/input before slow dispatch regardless of seen bits. Public ASCII misses now compose for arbitrary input lengths, covering word comparison, short buffers and exhausted tables, with fractional metadata and whole-input ownership. Public table-hit handling now covers every input length, including later-entry hits and seen expected entries; the cache fallthrough preserves state before actual search/mark. Whole-input ownership, exact key/suffix, pair/search-index updates, new bits and owned duplicate diagnostics are proved. Header/GasPrice table checks connect cached entries to their actual indexed schema names and canonical inline text encodings. A prefix theorem links encoded matches to decoded field names. The unified public NextField ASCII contract composes all cache/search paths into FieldReadOutcome for arbitrary inline/one-byte ASCII keys and field orders, including case variants, non-preferred one-byte lengths, unknown/new/duplicate outcomes, fractional metadata and exact FieldSearchAdvance with preserved next-iteration bounds. Cache/search fallback is factored into Hoare-composition lemmas with explicit leaf-proof arguments; the closed public contracts discharge those arguments with proved production helpers. Earlier cached hit/miss proofs reuse the common word-load proof. Public NextField now handles both integer major types and all five argument widths, returning unknown with exact consumption in range and owned range rejection with original cursor out of range. Public non-key type/tag rejection and text-body truncation, including oversized unsigned lengths, are proved with owned diagnostics, one-pair decrement, preserved search/seen/open state, fractional metadata and whole-input ownership. Pure head/prefix and truncation lemmas exclude false cache matches. All nonempty head failures (indefinite lengths, break codes, reserved/illegal additional information and incomplete extended arguments) now propagate through actual head/keySlow/Key and the complete NextField cache/search wrapper, including the incomplete 0x78 fast-path guard. Closed contracts instantiate the actual proved helpers, preserve original cursor/input and exact owned diagnostics, decrement the pair count once and retain fractional metadata and search/seen/open state. Earlier EOF proofs cover missing first bytes. Successful wider text heads, non-ASCII keys, UTF8 and initialization establishing shared ownership remain pending; older table examples still require exclusive ownership. Felt slow-loop error propagation now covers any valid prefix shorter than four limbs followed by a proved Uint64 error, preserving old output/input and restoring the array cursor/depth while retaining the inner diagnostic. The actual mixed-width shortcut now declines UnsignedReject input after any valid prefix shorter than four limbs without publishing temporary words; its offset is bounded by 28. A pure wire proof excludes a complete wide sequence on those rejected prefixes, and actual public dispatch checks all four wide guards before reaching the proved short rejection and slow rollback. Closed typed-reader contracts now cover type/tag, incomplete arguments and EOF for all array-head widths, including inline 0x84; they replace the earlier non-inline-four-only contracts. The actual extended loop also propagates Skip failure after four limbs and arbitrary valid ignored contents; closed typed-reader contracts cover EOF and all atomic SkipReject cases, including their post-head diagnostic offsets. These contracts instantiate actual helper proofs. HeadFault classifies all reserved/indefinite information codes and owns exact error arguments. Its closed head contract now composes through expectation and Uint64, all typed felt limb paths, malformed outer-array heads at any depth, and actual worker/public Skip dispatch. Malformed ignored elements after arbitrary valid contents compose through the typed felt reader, retaining inner diagnostic offsets and restoring outer cursor/depth/output. The outer-array proof includes head-error precedence over the depth limit. Closed outer type/tag, incomplete-argument and EOF contracts now compose through the actual typed felt reader at every depth, preserving old output/input/cursor and owned diagnostics. EOF is proved through actual Null, the empty shortcut and both public Limbs depth branches; unlike null/undefined, it preserves the old pointer. Incomplete heads of every major type now propagate through actual worker/public Skip, and through ignored felt contents after arbitrary valid extras with original inner offsets and outer rollback. The actual accepted-tag dispatch now propagates proved child failures. An independent SkipTagPrefix relation accounts for each encoded tag and chained-tag depth; induction proves all intermediate recursive calls. Closed worker/public contracts instantiate actual leaf proofs for malformed heads, incomplete arguments and atomic failures, preserving exact original-head or post-head diagnostic offsets and full-input ownership. Actual Peek EOF, missing tag content and the depth-limit branch are also proved; these compose through arbitrary supported tag prefixes with owned diagnostics, complete public cursor rollback and unchanged depth/scratch. Recursive array/map failures, complete Skip and felt rejection/converse, UTF8, byte-to-BigInt packing/carry, complete BigInt decoding, and whole-library correctness remain unproved.",
    "sha256": {str(p.relative_to(repo)): hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(set(inputs))},
}
(here / "results").mkdir(exist_ok=True)
(here / "results/proof-audit.json").write_text(json.dumps(report, indent=2) + "\n")
print(f"Audited {len(found)} pilot theorems: none depends on sorryAx or native evaluation axioms.")
